// Production four-language profile for Math parsing, including real Doc reader callbacks.
use nepl3_core::{budget::*, source::*};
use nepl3_core::{
    syntax::{Environment, EnvironmentEntry},
    value::NdfValue,
};
use nepl3_engine::{parse::*, profile::*, tree::ValidatedParseTree};
use nepl3_grammar_core::compile::package::CompiledLanguage;
use nepl3_reader::{
    model::{ProviderCall, ReadRequest, ReaderContext},
    runtime::ProviderReply,
};
use nepl3_wire::{environment::environment_digest, foundation::FoundationCodec};
fn err(v: impl std::fmt::Debug) -> String {
    format!("{v:?}")
}
fn with_input<T>(
    compiled: &Compiled,
    input: &str,
    category: &str,
    finish: impl FnOnce(
        &ValidatedParseTree<'_>,
        &ResolvedParseProfile<'_>,
        &mut Budget,
        &mut SourceAdmission,
    ) -> Result<T, String>,
) -> Result<T, String> {
    let r = &compiled.doc.registry;
    let packages: Vec<_> = std::iter::once(&compiled.doc.package)
        .chain(compiled.others.iter())
        .collect();
    // Each runtime registration identifies the actual source serving that operation.
    let implementation_for = |operation: &nepl3_core::value::OperationRef| {
        if operation.schema.package == "nepl3.doc.reader" {
            Digest::of(include_bytes!("C:/projects/NEPL3-prefix-validation/tools/src/doc/reader.rs"))
        } else {
            Digest::of(include_bytes!(
                "C:/projects/NEPL3-prefix-validation/crates/foundation/reader/src/builtin/provider.rs"
            ))
        }
    };
    let mut operations = Vec::new();
    for operation in packages
        .iter()
        .flat_map(|p| p.reader.providers.iter().map(|v| &v.operation))
    {
        if !operations.contains(operation) {
            operations.push(operation.clone());
        }
    }
    let providers: Vec<_> = operations
        .iter()
        .map(|operation| ProviderImplementation {
            provider: operation.name.clone(),
            revision: 1,
            implementation_digest: implementation_for(operation),
            operations: vec![operation.clone()],
        })
        .collect();
    let requirements = operations
        .iter()
        .map(|operation| ProviderRequirement {
            provider: operation.name.clone(),
            revision: 1,
            implementation_digest: implementation_for(operation),
            operation: operation.clone(),
        })
        .collect();
    let mut schemas = packages
        .iter()
        .map(|p| p.schema.clone())
        .collect::<Vec<_>>();
    for schema in packages
        .iter()
        .flat_map(|p| p.payload_schemas.iter())
        .chain(
            [
                "nepl3.foundation",
                "nepl3.reader",
                "nepl3.engine",
                "nepl3.doc",
                "nepl3.math",
                "nepl3.doc.reader",
                "nepl3.grammar",
            ]
            .iter()
            .filter_map(|name| r.selected(name, 1)),
        )
    {
        if !schemas.contains(schema) {
            schemas.push(schema.clone());
        }
    }
    let profile = ParseProfile {
        id: "math-prefix".into(),
        languages: packages
            .iter()
            .zip([
                ("Doc", "Article"),
                ("Math", "Expr"),
                ("Circuit", "Design"),
                ("Grammar", "Root"),
            ])
            .map(|(p, (alias, category))| {
                Ok(LanguageRegistration {
                    alias: alias.into(),
                    package: p
                        .check(r, &mut budget())
                        .and_then(|c| c.semantic_identity(&mut budget()))
                        .map_err(err)?,
                    default_category: category.into(),
                })
            })
            .collect::<Result<Vec<_>, String>>()?,
        schemas,
        head_providers: vec![],
        category_modes: vec![],
        providers: requirements,
        allowlist: operations,
        resources: vec![],
        limits: budget().limits(),
    };
    let resolved = profile
        .resolve(
            &RuntimeCatalog {
                packages: &packages,
                providers: &providers,
                resources: &[],
            },
            r,
            &mut budget(),
        )
        .map_err(err)?;
    let mut b = budget();
    let mut a = SourceAdmission::default();
    let source = SourceSnapshot::new(
        SourceId("math-input".into()),
        0,
        "memory:math-input".into(),
        input.as_bytes().to_vec(),
        &mut b,
    )
    .map_err(err)?;
    let tree = parse_source(&source, &resolved, category, &mut b, &mut a)?;
    let checked = tree.validate(&resolved, &mut b, &mut a).map_err(err)?;
    finish(&checked, &resolved, &mut b, &mut a)
}

fn parse_source(
    source: &SourceSnapshot,
    resolved: &ResolvedParseProfile<'_>,
    category: &str,
    b: &mut Budget,
    a: &mut SourceAdmission,
) -> Result<nepl3_engine::recovery::ParseTree, String> {
    parse_source_as(source, resolved, "Math", category, b, a)
}
fn parse_source_as(
    source: &SourceSnapshot,
    resolved: &ResolvedParseProfile<'_>,
    alias: &str,
    category: &str,
    b: &mut Budget,
    a: &mut SourceAdmission,
) -> Result<nepl3_engine::recovery::ParseTree, String> {
    let r = resolved.registry();
    let foundation = r.selected("nepl3.foundation", 1).ok_or("foundation")?;
    let mut store = SourceStore::default();
    store.insert(source.clone()).map_err(err)?;
    let value = Environment {
        bindings: vec![],
        resources: vec![],
    };
    let digest = environment_digest(&value, foundation, r, b).map_err(err)?;
    let mut contexts = Vec::new();
    for (alias, category) in [
        ("Doc", "Article"),
        ("Math", "Expr"),
        ("Circuit", "Design"),
        ("Grammar", "Root"),
    ] {
        let owner = resolved.language(alias, b).map_err(err)?;
        contexts.push(ReaderContext {
            schema: owner.schema.clone(),
            category: category.into(),
            mode: "Code".into(),
            origins: vec![],
            environment: EnvironmentEntry {
                id: 0,
                digest,
                value: value.clone(),
            },
        });
    }
    let environments = {
        let mut codec = FoundationCodec::new(r, &store, a).map_err(err)?;
        let checked = contexts
            .iter()
            .map(|raw| raw.check(&mut codec, &store, r, b).map_err(err))
            .collect::<Result<Vec<_>, String>>()?;
        let inputs = checked
            .iter()
            .zip(["Doc", "Math", "Circuit", "Grammar"])
            .map(|(context, alias)| EnvironmentInput { alias, context })
            .collect::<Vec<_>>();
        ParseEnvironmentSet::prepare(resolved, &inputs, &store, &mut codec, b)
            .map_err(|e| format!("environments: {e:?}"))?
    };
    let entry = resolved.entry(alias, Some(category), b).map_err(err)?;
    let states = ["Doc", "Math", "Circuit", "Grammar"].map(|alias| LanguageReaderState {
        alias: alias.into(),
        state: NdfValue::Unit,
    });
    let mut parser =
        ParseSession::new("doc-parse".into(), resolved, &environments, b).map_err(err)?;
    let mut result = parser
        .read(
            ParseRequest {
                snapshot: source,
                start: 0,
                limit: source.text().len() as u64,
                final_input: true,
                entry: &entry,
                states: &states,
            },
            &store,
            b,
            a,
        )
        .map_err(err)?;
    let mut reservations = 0;
    loop {
        match result.outcome {
            ParseOutcome::Await { call, continuation } => {
                let ProviderCall::Read {
                    operation,
                    request,
                    depth_base,
                    ..
                } = call.as_ref()
                else {
                    return Err("unexpected provider".into());
                };
                let mut declared = SourceStore::default();
                for source in &request.sources {
                    declared.insert(source.clone()).map_err(err)?;
                }
                let snapshot = declared
                    .resolve(&request.snapshot)
                    .ok_or("request source")?;
                let terminal = b
                    .with_depth_at_least(*depth_base, |b| {
                        let mut codec = FoundationCodec::new(r, &declared, a)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        let checked = request
                            .context
                            .check(&mut codec, &declared, r, b)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        (if operation.schema.package == "nepl3.doc.reader" {
                            nepl3_tools::doc::reader::read
                        } else {
                            nepl3_reader::builtin::provider::read
                        })(
                            operation,
                            ReadRequest {
                                snapshot,
                                start: request.start,
                                limit: request.limit,
                                final_input: request.final_input,
                                context: &checked,
                                state: &request.state,
                            },
                            r,
                            &declared,
                            b,
                            a,
                        )
                    })
                    .map_err(err)?;
                result = parser
                    .resume(
                        &continuation,
                        ProviderReply::Read(Box::new(terminal)),
                        &store,
                        b,
                        a,
                    )
                    .map_err(err)?;
            }
            ParseOutcome::Reserve { continuation, .. } => {
                reservations += 1;
                let reserved = SourceReservation {
                    source_id: SourceId(format!("decoded-{reservations}")),
                    revision: 0,
                    uri: format!("memory:decoded-{reservations}"),
                };
                result = parser
                    .reserve(&continuation, &reserved, &store, b, a)
                    .map_err(err)?;
            }
            ParseOutcome::Complete { tree, cursor, .. } => {
                assert_eq!(cursor, source.text().len() as u64);
                return Ok(tree);
            }
            other => return Err(format!("candidate: {other:?}")),
        }
    }
}

fn budget() -> Budget {
    Budget::new(Limits {
        source_bytes: 10_000_000,
        work: 100_000_000,
        depth: 1000,
        nodes: 1_000_000,
        allocation_units: 500_000_000,
        output_bytes: 10_000_000,
        diagnostics: 1000,
        events: 1000,
    })
}
struct Compiled {
    doc: CompiledLanguage,
    others: Vec<nepl3_engine::package::LanguagePackage>,
}
fn compiled() -> Result<Compiled, String> {
    let document = nepl3_tools::bootstrap::load(
        include_bytes!("C:/projects/NEPL3-prefix-validation/conformance/fixtures/doc/syntax.json"),
        &mut budget(),
        &mut SourceAdmission::default(),
    )
    .map_err(err)?;
    let mut doc = nepl3_tools::doc::catalog::compile(
        &document,
        "standard.doc",
        &mut budget(),
        &mut SourceAdmission::default(),
    )?;
    let mut others = Vec::new();
    for (name, seed) in [
        (
            "math",
            include_bytes!("C:/projects/NEPL3-prefix-validation/conformance/fixtures/doc/math.json").as_slice(),
        ),
        (
            "circuit",
            include_bytes!("C:/projects/NEPL3-prefix-validation/conformance/fixtures/doc/circuit.json").as_slice(),
        ),
        (
            "grammar",
            include_bytes!("C:/projects/NEPL3-prefix-validation/conformance/fixtures/doc/grammar.json").as_slice(),
        ),
    ] {
        let document =
            nepl3_tools::bootstrap::load(seed, &mut budget(), &mut SourceAdmission::default())
                .map_err(err)?;
        let other = nepl3_tools::doc::catalog::compile(
            &document,
            &format!("standard.{name}"),
            &mut budget(),
            &mut SourceAdmission::default(),
        )?;
        let schema = other.package.schema.clone();
        let descriptor = other
            .registry
            .descriptor(&schema)
            .ok_or("surface descriptor")?
            .clone();
        doc.registry
            .register(schema, descriptor, &mut budget())
            .map_err(err)?;
        others.push(other.package);
    }
    let descriptor = nepl3_math_core::schema::descriptor(&mut budget()).map_err(err)?;
    doc.registry
        .register(
            descriptor.reference(&mut budget()).map_err(err)?,
            descriptor,
            &mut budget(),
        )
        .map_err(err)?;
    doc.registry.finalize(&mut budget()).map_err(err)?;
    Ok(Compiled { doc, others })
}

use nepl3_core::{budget::{Budget,Limits,StopReason},value::{Integer,Rational},source::{SourceStore,SourceAdmission},schema::SchemaRegistry};
use nepl3_math_core::{model::*,number,construct,check::ShapeError,portable};
use nepl3_wire::foundation::FoundationCodec;
use num_bigint::{BigInt,BigUint};
fn err(e:impl std::fmt::Debug)->String{format!("{e:?}")}
fn b()->Budget{Budget::new(Limits{work:1_000_000_000,allocation_units:1_000_000_000,nodes:1_000_000,depth:200_000,source_bytes:1_000_000,output_bytes:10_000_000,diagnostics:100,events:100})}
fn q(n:i64,d:i64)->Result<Rational,String>{number::ratio(&Integer::from(n),&Integer::from(d),&mut b()).map_err(err)}
fn expected(q:&Rational,mut n:i64,mut d:i64){if d<0{n=-n;d=-d;}let(mut a,mut c)=(n.abs(),d);while c!=0{let r=a%c;a=c;c=r;}n/=a;d/=a;assert_eq!(q.numerator().as_bigint(),&BigInt::from(n));assert_eq!(q.denominator(),&BigUint::from(d as u64));}
fn node(kind:MathKind)->MathNode{MathNode{kind,span:None,origin:None,locations:vec![]}}
fn value(root:MathRoot,kinds:Vec<MathKind>)->MathValue{MathValue{root,nodes:kinds.into_iter().map(node).collect(),embeds:vec![]}}
fn symbol()->MathKind{MathKind::Symbol{name:"自由".into()}}
fn registry()->Result<SchemaRegistry,String>{let mut r=SchemaRegistry::default();for d in [nepl3_core::schema::foundation::descriptor(&mut b()),nepl3_math_core::schema::descriptor(&mut b())]{let d=d.map_err(err)?;r.register(d.reference(&mut b()).map_err(err)?,d,&mut b()).map_err(err)?;}r.finalize(&mut b()).map_err(err)?;Ok(r)}
fn main()->Result<(),String>{
 let mut operations=0;
 for (an,ad) in [(-7,12),(0,-5),(9,-15),(19,8),(1,125)]{for (cn,cd) in [(-2,7),(0,3),(11,-9),(3,10)]{
  let(a,c)=(q(an,ad)?,q(cn,cd)?);let originals=(a.clone(),c.clone());
  expected(&number::add(&a,&c,&mut b()).map_err(err)?,an*cd+cn*ad,ad*cd);
  expected(&number::subtract(&a,&c,&mut b()).map_err(err)?,an*cd-cn*ad,ad*cd);
  expected(&number::multiply(&a,&c,&mut b()).map_err(err)?,an*cn,ad*cd);
  if cn!=0{expected(&number::divide(&a,&c,&mut b()).map_err(err)?,an*cd,ad*cn);}else{assert_eq!(number::divide(&a,&c,&mut b()),Err(number::ArithmeticError::DivisionByZero));}
  expected(&number::negate(&a,&mut b()).map_err(err)?,-an,ad);assert_eq!((a,c),originals);operations+=5;
 }}
 let integer=Integer::from_bigint((BigInt::from(1_u64)<<256usize)+BigInt::from(12345_u64));let huge=number::ratio(&integer,&Integer::from(-125_i64),&mut b()).map_err(err)?;
 let product=number::multiply(&huge,&q(-125,1)?,&mut b()).map_err(err)?;assert_eq!(product.numerator(),&integer);assert_eq!(product.denominator(),&BigUint::from(1u64));
 for (n,d,finite) in [(6,30,true),(-14,56,true),(1,40,true),(1,6,false),(9,27,false),(0,19,true)]{
  let rational=q(n,d)?;assert_eq!(number::finite_decimal(&rational,&mut b()).map_err(err)?,finite);
  let required=if finite{1}else{2};for caller in [0,7]{for delta in [0,1]{let mut limits=b().limits();limits.depth=caller+required-delta;let mut budget=Budget::new(limits);let result=budget.with_depth_at_least(caller,|b|construct::expression_from_rational(&rational,b));
   if delta==1{assert_eq!(result,Err(number::ArithmeticError::Stopped(StopReason::DepthLimit)));assert_eq!(budget.poll(),Err(StopReason::DepthLimit));}else{let v=result.map_err(err)?;v.validate_shape(&mut b()).map_err(err)?;assert_eq!(budget.usage().depth,caller+required);assert_eq!(v.nodes.len(),if finite{1}else{3});}
   assert_eq!(budget.current_depth(),0);
  }}
 }
 for reason in [StopReason::WorkLimit,StopReason::AllocationLimit,StopReason::NodeLimit,StopReason::Cancelled]{let mut limits=b().limits();match reason{StopReason::WorkLimit=>limits.work=0,StopReason::AllocationLimit=>limits.allocation_units=0,StopReason::NodeLimit=>limits.nodes=0,_=>{}}let mut budget=Budget::new(limits);if reason==StopReason::Cancelled{budget.cancel();}assert_eq!(construct::expression_from_rational(&q(7,15)?,&mut budget),Err(number::ArithmeticError::Stopped(reason)));}
 for root in [MathRoot::Expr(ExprRef(u64::MAX)),MathRoot::Expr(ExprRef((1u64<<32)+1))]{assert!(matches!(value(root,vec![symbol(),symbol()]).validate_shape(&mut b()),Err(ShapeError::Reference(_))));}
 let shared=value(MathRoot::Expr(ExprRef(3)),vec![symbol(),MathKind::Neg{value:ExprRef(0)},MathKind::Neg{value:ExprRef(1)},MathKind::Add{left:ExprRef(0),right:ExprRef(2)}]);
 let mut limits=b().limits();limits.depth=3;assert_eq!(shared.validate_shape(&mut Budget::new(limits)).err(),Some(ShapeError::Stopped(StopReason::DepthLimit)));
 let mut budget=b();budget.with_depth_at_least(7,|b|shared.validate_shape(b)).map_err(err)?;assert_eq!(budget.usage().depth,11);
 assert!(value(MathRoot::Row(RowRef(0)),vec![MathKind::Row{values:vec![]}]).validate_shape(&mut b()).is_ok());
 assert!(value(MathRoot::Expr(ExprRef(0)),vec![MathKind::Sequence{values:vec![]}]).validate_shape(&mut b()).is_ok());
 assert_eq!(value(MathRoot::Expr(ExprRef(0)),vec![MathKind::Neg{value:ExprRef(0)}]).validate_shape(&mut b()).err(),Some(ShapeError::Cycle(0)));
 assert_eq!(value(MathRoot::Expr(ExprRef(0)),vec![symbol(),symbol()]).validate_shape(&mut b()).err(),Some(ShapeError::Unreachable(1)));
 let mut deep=vec![symbol()];for i in 0..100_000{deep.push(MathKind::Neg{value:ExprRef(i)});}let deep=value(MathRoot::Expr(ExprRef(100_000)),deep);deep.validate_shape(&mut b()).map_err(err)?;drop(deep);
 let r=registry()?;let syntax=MathSyntax{value:shared,sources:vec![],origins:vec![],views:vec![],source_maps:vec![]};
 let empty=SourceStore::default();let mut a=SourceAdmission::default();let mut codec=FoundationCodec::new(&r,&empty,&mut a).map_err(err)?;let raw=portable::to_value(&syntax,&r,&mut codec,&mut b()).map_err(err)?;
 let bytes=nepl3_wire::encode(&raw,&mut b()).map_err(err)?;let input=nepl3_wire::decode(&bytes,&mut b()).map_err(err)?;let mut a=SourceAdmission::default();let mut receiver=FoundationCodec::new(&r,&empty,&mut a).map_err(err)?;
 assert_eq!(portable::from_value(&input,&r,&mut receiver,&mut b()).map_err(err)?,syntax);
 println!("{operations} arithmetic checks against independent integer cross-product/gcd oracle; 256-bit result; finite-decimal constructors/caller limits; 32-bit reference boundaries; DAG/cycle/reachability/deep drop; source-less actual CBOR passed");Ok(())
}

